def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    cnt = Counter(c for row in grid for c in row)
    bg = cnt.most_common(1)[0][0]
    out = [row[:] for row in grid]
    # find the full-length uniform line
    line_color = None; horiz = None; pos = None
    for i in range(h):
        if len(set(grid[i])) == 1 and grid[i][0] != bg and grid[i][0] != 8:
            line_color, horiz, pos = grid[i][0], True, i
    if line_color is None:
        for j in range(w):
            col = [grid[i][j] for i in range(h)]
            if len(set(col)) == 1 and col[0] != bg and col[0] != 8:
                line_color, horiz, pos = col[0], False, j
    obj = [(i, j, grid[i][j]) for i in range(h) for j in range(w)
           if grid[i][j] != bg and grid[i][j] != line_color]
    if horiz:
        rows = [i for i, j, c in obj]
        top, bot = min(rows), max(rows)
        if pos > bot:
            shift = (pos - 1) - bot
        else:
            shift = (pos + 1) - top
        nt, nb = top + shift, bot + shift
        if 0 <= nt and nb < h:
            for i, j, c in obj:
                out[i][j] = bg
            for i, j, c in obj:
                out[i + shift][j] = c
        r = nt - 1 if pos > nb else nb + 1
        if 0 <= r < h:
            out[r] = [8] * w
    else:
        cols = [j for i, j, c in obj]
        left, right = min(cols), max(cols)
        if pos > right:
            shift = (pos - 1) - right
        else:
            shift = (pos + 1) - left
        nl, nr = left + shift, right + shift
        if 0 <= nl and nr < w:
            for i, j, c in obj:
                out[i][j] = bg
            for i, j, c in obj:
                out[i][j + shift] = c
        c2 = nl - 1 if pos > nr else nr + 1
        if 0 <= c2 < w:
            for i in range(h):
                out[i][c2] = 8
    return out
